(function(root){
  'use strict';
  const groups={campus:{name:'校园初遇',icon:'✿',caption:'走进教室，也走近彼此。'},daily:{name:'日常小剧场',icon:'☕',caption:'把熟悉的生活，变成日语练习。'},team:{name:'伙伴集结',icon:'☆',caption:'一起出发，接住伙伴的回应。'},courage:{name:'热血时刻',icon:'✧',caption:'把勇气，大声说出来。'}};
  const lines=[
    ['ohayou','campus','おはよう！','おはよう','ohayou','早上好！','清晨的教室，你向刚进门的同桌打招呼。','熟人之间的随意问候。对老师等可以说「おはようございます」。','长音','最后的「よう」通常连成长的 yo 音，不要把「う」读得太突出。','よ'],
    ['konnichiwa','campus','こんにちは。','こんにちは','konnichiwa','你好。','午后的走廊，遇到隔壁班刚认识的同学。','白天见面时的常用问候。','特殊读音','这里末尾的「は」读作 wa；单独学习这个假名时通常读 ha。','は'],
    ['arigatou','campus','ありがとう！','ありがとう','arigatou','谢谢！','同桌把你忘带的橡皮递了过来。','用于熟人之间。更礼貌的表达是「ありがとうございます」。','长音','「とう」通常连成长的 to 音；「が」带浊点。','が'],
    ['gomenne','campus','ごめんね。','ごめんね','gomen ne','对不起呀。','不小心撞到同学，你停下来道歉。','语气亲近、柔和，适合熟人之间的道歉。','拨音','「ん」占一拍；句尾的「ね」让语气更柔和。','ん'],
    ['mataashita','campus','また明日！','またあした','mata ashita','明天见！','社团活动结束，大家在校门口挥手。','约定明天再见时的轻松告别。','字形与读音','「明日」在这句中读「あした」；「し」的常见罗马音是 shi。','し'],
    ['yoroshikune','campus','よろしくね。','よろしくね','yoroshiku ne','以后请多关照。','第一次加入日语社，你向新伙伴做自我介绍。','用于初次认识、开始合作等场景；「ね」比较亲近。','字形与读音','「し」读 shi，「く」读 ku。先把假名连起来，再感受整句。','し'],
    ['tadaima','daily','ただいま！','ただいま','tadaima','我回来了！','推开家门，屋里传来饭菜的香味。','回到家时说的话，常与「おかえり」配成一组。','浊音','「だ」是「た」加浊点；不要和清音 ta 混淆。','だ'],
    ['okaeri','daily','おかえり！','おかえり','okaeri','欢迎回来！','听到玄关的声音，你回应刚回家的家人。','回应「ただいま」；更礼貌的形式是「おかえりなさい」。','字形与读音','「え」是 e，「り」是 ri。注意把每一拍读清楚。','り'],
    ['itadakimasu','daily','いただきます。','いただきます','itadakimasu','我开动了。','便当打开后，大家准备一起吃午饭。','开始吃饭前的惯用表达。','浊音','「だ」读 da；句末「す」在自然语流中常有元音清化。','だ'],
    ['gochisousama','daily','ごちそうさまでした。','ごちそうさまでした','gochisousama deshita','多谢款待。','吃完晚饭，你向准备饭菜的人表达感谢。','吃完饭时的常用表达。','长音','「そう」通常连成长的 so 音；「ち」读 chi。','ち'],
    ['oyasumi','daily','おやすみ。','おやすみ','oyasumi','晚安。','夜深了，你在聊天结束前向朋友道晚安。','熟人之间的晚安；礼貌形式是「おやすみなさい」。','字形与读音','「や」读 ya，「み」读 mi。可以先分别回忆再连读。','や'],
    ['chottomatte','daily','ちょっと待って！','ちょっとまって','chotto matte','等一下！','电车快开了，你追上正准备出发的伙伴。','随意的请求。根据语气，可以急切，也可以轻声提醒。','拗音与促音','「ちょ」合读一拍；两个「っ」都表示后接辅音前的短暂停顿。','っ'],
    ['makasete','team','任せて！','まかせて','makasete','交给我吧！','文化祭海报还没完成，你举手接下任务。','主动承担任务、让对方放心的随意表达。','字形与读音','「せ」读 se。注意区分字形相近的「せ」与「さ」。','せ'],
    ['isshoniikou','team','一緒に行こう！','いっしょにいこう','issho ni ikou','一起走吧！','放学后，伙伴邀请你一起去社团教室。','向熟人发出一起行动的邀请。','促音与拗音','「っ」先停一拍，「しょ」合读一拍；末尾「こう」是长音。','しょ'],
    ['ikuzo','team','行くぞ！','いくぞ','iku zo','出发啦！','冒险队在入口集合，领队朝大家挥手。','强势、随意的招呼，常对熟悉的伙伴说；更礼貌可用「行きましょう」。','浊音','「ぞ」读 zo；它是「そ」加浊点，句尾语气较强。','ぞ'],
    ['yatta','team','やった！','やった','yatta','太好了！','准备许久的社团演出终于顺利完成。','成功、得知好消息时的兴奋感叹。','促音','「っ」不单独发出 tsu 音；在「た」前停一拍，像 yat-ta。','っ'],
    ['kiwotsukete','team','気をつけて！','きをつけて','ki o tsukete','小心一点！','雨后的台阶有些滑，你提醒走在前面的朋友。','提醒别人注意安全，也可在告别时表达关心。','助词读音','这里的「を」是助词，读 o；「つ」读 tsu。','を'],
    ['tasukete','team','助けて！','たすけて','tasukete','帮帮我！','布置展台时搬不动道具，你向附近的伙伴求助。','直接的求助表达，紧急时也会使用。','字形与读音','「す」读 su，「け」读 ke。把「すけ」连起来回忆。','け'],
    ['daijoubu','courage','大丈夫！','だいじょうぶ','daijoubu','没关系，我没事！','练习失误后，你向担心的同伴笑着摆摆手。','可表示没事、不要紧；升调说「大丈夫？」也能询问对方是否还好。','拗音与长音','「じょ」合读一拍；后面的「う」让 jo 拉长。「だ」「ぶ」都是浊音。','じょ'],
    ['ganbatte','courage','頑張って！','がんばって','ganbatte','加油！','轮到朋友上台了，你在台下为他打气。','对正在努力或即将挑战的人表达鼓励。','拨音与促音','「ん」与「っ」各占一拍；「っ」接在「て」前形成停顿。','っ'],
    ['akiramenai','courage','諦めない！','あきらめない','akiramenai','我不会放弃！','尝试几次仍没成功，主角重新站到起点。','表达自己不放弃的决心，通常是比较随意的语气。','字形与读音','「ら」读 ra，「な」读 na。注意不要把这两个字形混淆。','ら'],
    ['shinjiteru','courage','信じてる。','しんじてる','shinjiteru','我相信你。','伙伴即将面对挑战，你认真地向他点头。','此处省略了语境中明确的对象；「てる」是「ている」的口语形式。','浊音','「し」读 shi，加浊点后「じ」读 ji。听听两个声音的区别。','じ'],
    ['yakusokudayo','courage','約束だよ。','やくそくだよ','yakusoku da yo','约好了哦。','两人在放学路上约定，下次文化祭还要一起参加。','强调彼此的约定，语气亲近。','浊音','「だ」读 da；句尾「よ」用于向对方传达、强调自己的话。','だ'],
    ['zettainimakenai','courage','絶対に負けない！','ぜったいにまけない','zettai ni makenai','我绝不会认输！','决赛开始前，主角握紧拳头给自己鼓劲。','强烈表达自己的决心，适合热血的剧情情境。','浊音与促音','「ぜ」是浊音；「っ」在「た」前停一拍，像 zet-tai。','っ']
  ].map(([id,group,text,kana,romaji,meaning,scene,usage,topic,note,focus])=>({id,group,text,kana,romaji,meaning,scene,usage,topic,note,focus}));
  function tokenize(kana){const result=[];for(const c of kana){if(/[ゃゅょャュョ]/.test(c)&&result.length)result[result.length-1]+=c;else result.push(c);}return result;}
  function spokenToken(line,index){const token=tokenize(line.kana)[index];return token==='を'?'お':line.id==='konnichiwa'&&index===4?'わ':token;}
  const api={groups,lines,tokenize,spokenToken};root.KanaDialogueData=api;if(typeof module!=='undefined')module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
